window.VD=window.VD||{};window.VD["vw/touran-1t"]={"touran-1t-activate-turn-signals-in-us-mode":"<p><strong>Purpose:</strong> Enables the US turn signals.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><strong>Byte 7</strong>: Set value<strong> 32</strong> in <strong>Dec</strong> box (value in % of intensity, origin: 0)</p>\n<p>Decimal examples shown in yellow in the image:<br/>14 (corresponds to a 20% variation in the indicator lights)<br/>1E (corresponds to a 30% variation in the indicator lights)<br/>28 (corresponds to a 40% variation in the indicator lights)</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/3C0-937-049-Q_Module09_Byte7-16502f21.webp\"/></figure>","touran-1t-adjusting-light-sensor-sensitivity":"<p><strong>Purpose: </strong>Adjusts the sensitivity of the light sensor.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1 (1T):</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “2 EPIRBs” module from the drop-down list and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>2</strong>: </em><br/> Bits<em><strong> 0-7</strong></em> (187, 205 or 237 to increase sensitivity, or 45, 40 or 33 to decrease sensitivity)</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/lightsensorg5-1e88d9a5.webp\"/></figure>\n<hr/>\n<p><strong>Line 1 (1T2):</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “2 EPIRBs” module from the drop-down list and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>0</strong>:  </em><br/><em>Bits <strong>3–4</strong>: Select from the drop-down list<br/>– 00 Normal light activation threshold<br/>– 08 Earlier light activation threshold (+20%)<br/>– 10 Light Activation Threshold earlier (+40%)<br/>– 08 Light Activation Threshold earlier (+60%)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Calc09-RLS-140kmhBit0-Octet0-4f74e4e9.webp\"/></figure>","touran-1t-ambient-lighting-intensity":"<p><strong>Purpose:</strong> Used to adjust ambient lighting intensity.  </p>\n<p><strong>Procedure</strong>: <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select</strong>” then click on “<strong>09 – Cent. Elect.</strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation 10</strong>”.</p>\n<p><strong>5</strong> – Select <strong>Channel 05</strong> (Footwell Lightning Dimming)  </p>\n<p><strong>6 –</strong> Select intensity from 20 to 100% (in 1% increments)</p>","touran-1t-automatic-closing-of-windows-and-roof-in-case-of-rain":"<p><strong>Purpose</strong>: Automatically closes the windows and sunroof when it rains. </p>\n<p>The vehicle must be locked using the remote control for this to work. </p>\n<p><strong>Procedure:</strong> <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/>3 – Click on ” <strong>Select</strong> “, then click on ” <strong>09 – Cent. Elect.</strong>” . Switch on the ignition and run the VCDS program. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vitregolf561-c90da3e5.webp\"/></figure>\n<p><strong>5</strong> – Select module “2” and click ” <strong>Long Coding Helper</strong> “:</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vitregolf56-9439cbb9.webp\"/></figure>\n<p><strong>6</strong> – In the window that appears, select byte <strong>0 and </strong>check bit<strong> 2</strong>, <strong>“Rain Closing active</strong>,” to enable the windows and roof to close when it rains:</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Vag-Com-Fermeture-Automatique-des-vitres-5-d61c5dd9.webp\"/></figure>\n<p>7 – After completing this step, click on the “Exit” menu</p>\n<p> Then click “OK”</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Vag-Com-Fermeture-Automatique-des-vitres-7-353fb01b.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p><strong>3</strong> – Click <strong>“Select</strong>,” then click <strong>“46 – Central Conv”</strong> </p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5 –</strong> Then click <strong>” <strong>Long Coding Helper</strong> “</strong></p>\n<p><em><strong>6</strong> – Select Byte <strong>9</strong>: </em><br/><em>Bit <strong>1</strong>: Check “Rain Closing (0 = nonrecurring / 1 = permanent)” </em><br/><em>Bit<strong> 2</strong>: Uncheck “Comfort Closing via Rain Light Sensor (Rain Closing) inactive” </em> </p>","touran-1t-automatic-door-locking":"<p><strong>Purpose:</strong> to set automatic door locking from 15km/h.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>Channel 04</strong></p>\n<p><em>Set value to 1</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Verrouillage-automatique-des-portieres_vw-auto-loc-ce03b1da.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p>If the adaptation channel is not activated.</p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>4</strong>: Check “Auto-Lock (automatic locking from 15 km/h)”. </em> </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Verrouillage-automatique-des-portieres-1K0_Module4-be0b33ff.webp\"/></figure>","touran-1t-automatic-door-unlocking":"<p><strong>Purpose:</strong> to set automatic door unlocking when the ignition key is removed.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>Canal 05</strong></p>\n<p><em>Set value to 1</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw-door-unlock-798a1163.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p>If the adaptation channel is not activated.</p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte<strong> 0</strong>: </em><br/><em>Bit <strong>3 : </strong> Check “Auto-Unlock (unlocking after removing key from ignition)”. </em> </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Verrouillage-automatique-des-portieres-1K0_Module4-be0b33ff.webp\"/></figure>","touran-1t-automatic-headlamp-activation-from-140-km-h":"<p><strong>Purpose: </strong>to automatically switch on the lights when the vehicle is travelling at over 140 km/h. </p>\n<p>(The lights will automatically go out if the vehicle is travelling at less than 60 km/h) </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “2 EPIRBs” module from the drop-down list and click on “Long Coding Helper”:</p>\n<p>Byte <strong>0</strong> Bit <strong>0</strong>: Check “Highway Light Function active above (140kph/90mph)”.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Calc09-RLS-140kmhBit0-Octet0-4f74e4e9.webp\"/></figure>","touran-1t-automatic-headlamp-activation-in-case-of-rain":"<p><strong>Purpose:</strong> to automatically turn on the lights when it’s raining and the wipers have been triggered.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “2 EPIRBs” module from the drop-down list and click on “Long Coding Helper”:</p>\n<p>Byte <strong>0</strong> Bit <strong>1</strong>: Check “Rain Light Function Active”.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Calc09-RLS-140kmhBit0-Octet0-4f74e4e9.webp\"/></figure>","touran-1t-coming-home-time-setting":"<p><strong>Purpose:</strong> Set the length of time the headlights remain on after the car is locked.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on <strong>“Adaptation – 10”</strong> </p>\n<p><strong>5</strong> – Select <strong>Channel 01</strong> (Coming-Home Time)  </p>\n<p><strong>6</strong> – Select duration from <strong>0 to 60 sec</strong> (in 1sec increments).</p>","touran-1t-corner-lights-activation":"<p><strong>Purpose</strong>: Activating the <strong>cornering lights</strong> causes the fog light on the side toward which you’re turning the steering wheel to turn on when traveling at speeds below 50 km/h. This feature is also known as “cornering lights.” Once this feature is activated on your Touran, the fog light on the side of the turn you’re making will turn on! It’s super handy on narrow roads or in roundabouts.   </p>\n<p><strong>This modification is only available for vehicles equipped with a 30-byte power unit.</strong> </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition switched off, connect your official VAG-COM VCDS cable to the computer, then connect the other end to your vehicle’s diagnostic port.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>23</strong>: </em><br/><em>Bit <strong>2</strong>: Check “Internal Turn Light Control Algorithm active”</em><br/><em>Bits <strong>3–4</strong>: Select “08 Turn Lights via fog lights” from the drop-down list</em></p>","touran-1t-correction-of-odb-consumption-display":"<p><strong>Purpose</strong>: to correct the fuel consumption display on the on-board computer.  </p>\n<p><strong>Modification only possible on Mid/High range models</strong>. <br/><em>Note: modifications affect the display of instantaneous consumption, average consumption and fuel quantity.</em></p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on <strong>“17 – Instruments”</strong>. <strong>Procedure:</strong> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on<strong>“Adaptation- 10</strong>”.</p>\n<p><strong>5</strong> – Select <strong>Channel 03</strong> <em>“Consumption Correction”.</em></p>\n<p><em>Adjust consumption correction factor between 85% and 115%.</em> <em>(base value: 100)</em></p>\n<p><em>Example 1: Calculation based on volume per distance (e.g. l/100 km): DIS: 9.3 l/100 km. Actual: 9.8 l/100 km. (100, 9,8 / 9,73 ? 105,38) Channel 3 will be changed from 100 to 105 <br/>Example 2: Calculation based on volume distance (e.g. MPG is: DIS: 23 MPG. Actual: 24 MPG. (100, 23/24 and 95.83) Channel 3 will be changed from 100 to 96</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/correction-consommation-odb-d51db18e.webp\"/></figure>","touran-1t-cruise-control-activation-retrofit":"<p><strong>Purpose:</strong> to activate the speed governor after retrofitting.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>01 – Motor</strong> “.</p>\n<p><strong>4</strong> – Click on ” <strong><strong>Access</strong></strong> – <strong> 11</strong> ” then enter the code ” <strong><em><strong>11463</strong></em></strong> ” </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/regulateur2-6871f13e.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>16 – Steering Wheel</strong>“.</p>\n<p><strong>4</strong> – Click on ” <strong>Coding – 07</strong> ” then </p>\n<p><em>The penultimate digit (0xxxx<strong>?</strong>x) is used to configure the cruise control.</em><br/><em>Enter <strong>2</strong> if you don’t have an on-board computer</em><br/><em>Set <strong>4</strong> if you have an on-board computer</em></p>\n<p>.</p>","touran-1t-deactivate-brake-pad-warning-light":"<p><strong>Purpose: </strong> Allows you to disable the brake pad wear warning light on the OBD (On-Board Diagnostics) system, for example, for brake pads without a sensor or if the sensor is malfunctioning / Brake Pad Warning Light Deactivation. </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>17 – Instruments</strong>.”<br/><br/><strong>4 – </strong>Click on <strong>“Coding –</strong> 07”  </p>\n<p><strong>5</strong> <em>–  <em>The third and fourth digits of the code (xx<strong>??</strong>x0x) are used to change the settings for the Instrument module. To turn off the brake pad warning light, subtract <strong>01</strong> from these digits. </em></em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/17-Instruments-Coding-Golf5-2c5d8d07.webp\"/></figure>\n<p>In the example above, the initial code is: <strong>0027103</strong></p>\n<p>To turn off the brake pad warning light, simply recode it as follows: <strong>0026103 </strong><em>(27 – 01 = 26)</em></p>\n<p>To turn on the brake pad warning light: +01</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant-frein-d4619ec9.gif\"/></figure>","touran-1t-deactivate-burnt-out-bulb-display":"<p><strong>Purpose: </strong>To deactivate the burnt-out bulb indicator on the ODB (on-board computer). After adding LEDs, your on-board computer may indicate that the replaced bulb is out of order.   </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p>Byte <strong>18</strong> Bit<strong> 0</strong>: Uncheck “Cold Diagnosis License Plate Lights active” for plates</p>\n<p>the other bits for the other bulbs of your choice (see image)</p>\n<p>Byte 19 Bit 1: uncheck “Cold Diagnosis Front Parking Lights active” for night lights</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_6231-0119a9fa.webp\"/></figure>\n<p>Or for all bulbs:</p>\n<p>Byte 2 Bit 2: Cold Lamp Diagnosis Active</p>\n<p><br/>Eliminate burnt-out bulb errors after coding.</p>","touran-1t-deactivate-rear-wiper-when-reversing":"<p><strong>Purpose:</strong> to deactivate automatic activation of the rear windshield wiper during reversing when the front windshield wipers are operating.  </p>\n<p><strong>Procedure:</strong> <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/>3 – Click on ” <strong>Select</strong> “, then click on ” <strong>09 – Cent. Elect.</strong>” . Switch on the ignition and run the VCDS program. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><em><strong>Byte 1 :</strong></em><br/><em><strong>Bit 7 </strong>: Uncheck “Rear Wiper with Front Wiper continiously active”.</em></p>\n<p><em><strong>Byte 2 : </strong></em><br/><em><strong>Bit 0</strong>: Uncheck “Rear Wiper with Front Wiper intermitent active”.</em></p>","touran-1t-deactivate-windshield-washer-indicator":"<p><strong>Purpose </strong>: to deactivate the windshield washer indicator on the ODB (on-board computer).  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.<br/><br/><strong>4 </strong>– Click on “<strong>Coding – 07</strong>”.  </p>\n<p><strong>5</strong> <em>–  <em>The third and fourth coding digits (xx<strong>??</strong>x0x) are used to modify Instrument module options. To remove the ice-washer indicator, subtract <strong>04</strong> from these digits. </em></em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/17-Instruments-Coding-Golf5-2c5d8d07.webp\"/></figure>\n<p>In the example above, the initial coding is: <strong>0027103</strong></p>\n<p>To remove the windscreen washer indicator, simply recode as follows: <strong>0023103 </strong><em>(27 – 04 = 23)</em></p>\n<p>To activate the ice washer indicator: +04</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/laveglace-edc83d4f.webp\"/></figure>","touran-1t-defrost-time-setting":"<p><strong>Purpose:</strong> to set the operating time for mirror and rear window defrosting.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong> then click on “<strong>09 – Cent. Elect.</strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 03</strong> (Rear Window &amp; Outside Mirror Heater Activation Time)  </p>\n<p><strong>6</strong> – Select duration from <strong>1 to 254 min</strong> (in 1 min increments).</p>","touran-1t-delete-belt-alarm":"<p><strong>Purpose</strong>: To suppress the audible alarm and the warning light on the speedometer when driving without a seatbelt.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>17 – Instruments</strong>”. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “<strong>Coding 07</strong>”.</p>\n<p><strong>5</strong> –  <em>The third and fourth coding digits (xx<strong>??</strong>x0x) are used to modify Instrument module options. To suppress the belt alarm, subtract <strong>2</strong> from these digits. </em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/17-Instruments-Coding-Golf5-2c5d8d07.webp\"/></figure>\n<p>In the example above, the initial coding (with belt alarm) is: <strong>0023103</strong></p>\n<p>To delete the belt alarm, simply recode as follows: <strong>0021103 </strong><em>(23 – 02 = 21)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant_ceinture_de_securite-296648a9.webp\"/></figure>","touran-1t-display-speed-on-rcd-300":"<p><strong>Purpose:</strong> To add a driving-school mode view to the RCD 300 that displays speed (also ideal for accompanied driving) <br/><br/><br/><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket. <br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“56 – Radio</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Channel 2</strong>” “Driving School Function”.<br/><br/><strong>7</strong> – Set value to <strong>1</strong>.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/RCD300_Module56_Channel02-3c0994f0.webp\"/></figure>\n<p>To activate the function:<br/>– Switch off the RCD-300<br/>– Press the MENU button<br/>– Keep the MENU button pressed and switch on the RCD-300.</p>\n<p><em>(To return to normal display, execute the same sequence)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw_rcd300-efa2d2ba.webp\"/></figure>","touran-1t-door-lock-confirmation-key":"<p><strong>Purpose: </strong> Allows you to configure the door lock confirmation when using the key.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.<br/><br/><strong>4 – </strong> Click “<strong>Adaptation – 10</strong>“</p>\n<p><strong>Channel 11</strong></p>\n<p><em>Set the value to 0 (no confirmation)</em><br/><em>Set the value to 1 (confirmation with turn signals)</em><br/><em>Set the value to 2 (confirmation with beep/horn)</em><br/><em>Set the value to 3 (confirmation with turn signals and a beep/horn)</em></p>\n<p><strong>Line 2: </strong></p>\n<p>If the adaptation channel is not activated.</p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte <strong>11</strong>: </em><br/><em>Bit <strong>0: </strong> Check “Locking Confirmation (Blink) via Door Locks” (confirmation with blinking lights)</em><br/><em>Bit <strong>1</strong>: Check “Locking Confirmation (Horn) via Door Locks” (confirmation with a beep or horn)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/locking_196-096e4b1a.webp\"/></figure>","touran-1t-door-lock-confirmation-remote-control":"<p><strong>Purpose: </strong> Allows you to configure the door lock confirmation when using the remote control. </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>Channel 10</strong></p>\n<p><em>Set the value to 0 (no confirmation)</em><br/><em>Set the value to 1 (confirmation with turn signals)</em><br/><em>Set the value to 2 (confirmation with beep/horn)</em><br/><em>Set the value to 3 (confirmation with turn signals and a beep/horn)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vagcom-golf5-e5c80be6.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p>If the adaptation channel is not activated.</p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte <strong>11</strong>: </em><br/><em>Bit <strong>2: </strong> Check “Locking Confirmation (Blink) via Remote Control” (confirmation with turn signals)</em><br/><em>Bit <strong>3</strong>: Check “Locking Confirmation (Horn) via Remote Control” (confirmation with a beep or horn)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/locking_196-096e4b1a.webp\"/></figure>","touran-1t-door-unlock-confirmation-key":"<p><strong>Purpose: </strong> Allows you to configure the door unlock confirmation when using the key.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>Channel 08</strong></p>\n<p><em>Set the value to 0 (no confirmation)</em><br/><em>Set the value to 1 (confirmation with turn signals)</em><br/><em>Set the value to 2 (confirmation with beep/horn)</em><br/><em>Set the value to 3 (confirmation with turn signals and a beep/horn)</em></p>\n<p><strong>Line 2:</strong></p>\n<p>If the adaptation channel is not activated.</p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte <strong>10</strong>: </em><br/><em>Bit <strong>0</strong>: Check “Unlocking Confirmation (Blink) via Door Locks” (confirmation with blinking lights)</em><br/><em>Bit <strong>1</strong>: Check “Unlocking Confirmation (Horn) via Door Locks” (confirmation with a beep or horn)</em></p>","touran-1t-door-unlock-confirmation-remote-control":"<p><strong>Purpose </strong>: to set the door unlock confirmation when using the remote control.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>Channel 07</strong></p>\n<p><em>Set the value to 0 (no confirmation)</em><br/><em>Set the value to 1 (confirmation with turn signals)</em><br/><em>Set the value to 2 (confirmation with beep/horn)</em><br/><em>Set the value to 3 (confirmation with turn signals and a beep/horn)</em></p>\n<p><strong>Line 2:</strong></p>\n<p>If the adaptation channel is not activated.</p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte <strong>10</strong>: </em><br/><em>Bit<strong> 2</strong>: Check “Unlocking Confirmation (Blink) via Remote Control” (confirmation with flashing lights)</em><br/><em>Bit <strong>3</strong>: Tick “Unlocking Confirmation (Horn) via Remote Control” (confirmation with Beep/Horn)</em></p>","touran-1t-flash-mode-lights-during-emergency-braking":"<p><strong>Purpose</strong>: activates brake lights in flash mode during emergency braking.  </p>\n<p><strong>Procedure </strong>: <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>17</strong>: </em><br/><em>Bit <strong>0</strong>: Check “Emergency Brake Flash Light active”.</em></p>","touran-1t-fold-down-mirrors-with-ignition-off-and-door-open":"<p><strong>Purpose </strong>: Allows mirrors to be folded down even after the ignition has been switched off and a door opened.  </p>\n<p><em>(Also enables windows and sunroof to be closed)</em> </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>46 – Comfort Module</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on “<strong>Long Coding Helper</strong>” .</p>\n<p><em>Byte <strong>6 : </strong></em><br/><em>Bit <strong>7: </strong> Uncheck “Power Windows/Sunroof disabled after door Opening”.</em></p>","touran-1t-headlight-washer-duration-setting":"<p><strong>Purpose:</strong> Allows you to set how long the headlight washers remain activated.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on <strong>“Adaptation – 10”</strong> </p>\n<p><strong>5</strong> – Select <strong>Channel 04</strong> (Headlight Washer Activation Time)  </p>\n<p><strong>6</strong> – Select a duration between <strong>50 and 10,000 ms</strong> (in 50-ms increments).</p>","touran-1t-leaving-home-duration-setting":"<p><strong>Purpose:</strong> to set the length of time the headlights remain on after the car is unlocked.  </p>\n<p><strong>Procedure: </strong> <br/><strong>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</strong> </p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on <strong>“Adaptation – 10”</strong> </p>\n<p><strong>5</strong> – Select <strong>Channel 02</strong> (Leaving-Home Time)  </p>\n<p><strong>6</strong> – Select duration from <strong>0 to 60 sec</strong> (in 1sec increments).</p>","touran-1t-leaving-home-without-light-sensor":"<p><strong>Purpose</strong>: automatically switches on the headlights each time the vehicle is unlocked.  </p>\n<p>The headlights will come on whether it’s day or night. They stay on for about 30 sec.   </p>\n<p><strong>Procedure:</strong> <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/>3 – Click on ” <strong>Select</strong> “, then click on ” <strong>09 – Cent. Elect.</strong>” . Switch on the ignition and run the VCDS program. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click ” <strong>Encoding 07</strong>,” then “Long Coding Helper”</p>\n<p><strong>5 –</strong> <em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>5</strong>: Check “Driving Light Assistance When Leaving Home active”</em></p>","touran-1t-one-touch-window-closing":"<p><strong>Purpose</strong>: to activate closing and opening of the windows and sunroof with the remote control <strong>WITHOUT </strong>remaining pressed until the windows are completely closed.  </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition turned off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic port.<br/><br/><strong></strong> 2 – Turn on the ignition and launch the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>46 – Central Conv.”</strong></p>\n<p><strong>4</strong> – Click ” <strong>Encoding 07</strong>,” then “Long Coding Helper”</p>\n<p><strong>5 –</strong> <em>Byte <strong>6</strong>: </em><br/><em>Bit <strong>6</strong>: Check “Comfort Function automatic Closing”.</em></p>\n<ul>\n<li>Uncheck “Comfort function power windows/sunroof via remote control inactive”.</li>\n<li>Check “Comfort opening power windows via remote control active”.</li>\n<li>Check “Comfort closing power windows via remote control active”.</li>\n<li>Check “Closing sunroof via remote control active” (sunroof)</li>\n</ul>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/ComfortConv-byte6-9f2c129f.webp\"/></figure>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>46 – Comfort Module.”</strong><br/><br/><strong>4 – </strong>Click “ <strong>Adaptation – 10”</strong> </p>\n<p><strong>Channel 17</strong> (Comfort function)</p>\n<p><em>Set value to 1</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_0944-1024x741-ec4d5180.webp\"/></figure>\n<p><em>Pressing the remote control’s close button for 3 seconds will first lock the doors and then close the windows, without having to keep the button pressed until they are fully closed</em>.</p>","touran-1t-programming-a-remote-control":"<p><strong>Purpose:</strong> Allows you to program the remote controls that will be used with the vehicle for central locking and unlocking.  </p>\n<p>⚠️ <strong>WARNING:</strong> This procedure does not allow you to program the remote controls with the vehicle’s immobilizer.</p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 01 ( </strong>“Remote Control Adaptation” from the drop-down list)</p>\n<p>Enter the number of keys to program, then click <strong>Save</strong>.<br/>Next, press the <strong>Unlock</strong> button on each remote control to be programmed for at least 1 second. The flashing lights will confirm the procedure.<br/>All keys must be programmed in a single session, one after the other.<br/>Programming all keys must not take longer than <strong>15 seconds</strong>.<br/>You can add up to <strong>4 remote controls</strong>. If the <strong>[Test]</strong> and/or <strong>[Save]</strong> buttons are grayed out and unclickable, the module likely has all 4 slots filled; delete the remote controls using the <strong> “Reset Remote Controls”</strong> tutorial.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6Q0-959-433-E_Module46_Adaptation_Channel01-10148edb.webp\"/></figure>","touran-1t-reset-the-remote-controls":"<p><strong>Purpose:</strong> Resets the settings for all remote controls associated with the vehicle.</p>\n<p><strong>⚠️ WARNING:</strong> After completing this procedure, all remote controls will be deleted and will need to be reprogrammed using the <strong>“How to Program a Remote Control”</strong> tutorial <strong>.</strong></p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 00</strong></p>\n<p><em>Set the value to <strong>0</strong> and save</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6Q0-959-433-E_Module46_Adaptation_Channel00-caced031.webp\"/></figure>","touran-1t-selective-door-unlocking":"<p><strong>Purpose </strong>: Used to set up selective door unlocking. </p>\n<p>When unlocking the vehicle, only the driver’s door is unlocked. To unlock all doors, press the remote control’s unlock button twice.   </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>Channel 03</strong></p>\n<p><em>Set value to 1</em></p>\n<p><strong>Line 2:</strong></p>\n<p>If the adaptation channel is not activated.</p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>0</strong>: Check “Selective Central Locking (Single Door Opening)” </em> </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Verrouillage-automatique-des-portieres-1K0_Module4-be0b33ff.webp\"/></figure>","touran-1t-show-hidden-menu-climatronic":"<p><strong>Purpose: </strong>to display the Climatronic’s hidden menu.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/menu-cache-climatronic-golf5-7154b4a2.webp\"/></figure>\n<p><strong>Displaying instantaneous digital speed? it’s possible! </strong>  No need to use your VCDS VAG-COM cable for this tutorial.</p>\n<p><strong>Proceed :</strong></p>\n<p>It’s really quite simple. <strong>Just press the “ECON” button on your air conditioner and the “air extraction up” button, symbolized by a person with an arrow pointing upwards, at the same time</strong>.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/climatronic1-5edb6af4.gif\"/></figure>\n<p>Then simply move the driver-side climate control knob to access the various temperatures and functions.</p>\n<p><strong>What’s it for?</strong></p>\n<p>The main things to check are engine temperature, cabin temperature, exterior temperature and digital speed.</p>\n<p>For digital speed:  </p>\n<p>Then set to -19.0 in the left-hand display by turning the left-hand knob, and the right-hand display gives you the “real” speed in km/h.</p>\n<p>This is because the “real” speedometer is different from the analogue speedometer (needle) which has passed 60km/h.</p>\n<p>Above 99km/h, the right display alternates between the 100km/h in the small right-hand corner and the remaining two digits in the large right-hand corner.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/climatronic2-1d05bbc0.gif\"/></figure>\n<p>Turning the central knob changes the small exponent number on the left display, which changes the display on the right to a small 2 – the speed is in mph.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/climatronic3-04295505.gif\"/></figure>\n<hr/>\n<p><strong>List of hidden Climatronic functions</strong></p>\n<p><br/>The beginning of each paragraph symbolizes a function (1st line) followed by sub-functions (following lines).</p>\n<p><strong>0</strong> System data (temperature setting left)<br/>0 Program number Dig. (temperature setting right)<br/>1 ERL disaster Dig.<br/>2 ERL right Dig.<br/>3 Working point on/on Dig.<br/>4 Automatic ricircolo (motor)/Automatic ricircolo Bit Dig.<br/>5 Heating as stopped I activate Dig.<br/>6 Air quality<br/>7 Derivative Dig.<br/>8 Country code Dig.<br/>9 Zone sensor test °C </p>\n<p><strong>1</strong> UIF (temperature setting left)<br/>0 Internal temperature °C (temperature setting right)<br/>1 Surface temperature °C<br/>2 Platinum piastrin temperature (?) °C<br/>3 Platinum piastrin corrector (?) °C<br/>4 uif-Sonnenint (?) Dig.<br/>5 Radiation corrector (?) °C<br/>6 Dynamic correctors °C<br/>7 Ricircolo corrector °C<br/>8 Thermal correctors °C<br/>9 UIF ignition compensation °C</p>\n<p><strong>2</strong> Irradiance sensor SX<br/>0 Irradiance not delayed (?) W/m2<br/>1 Irradiance corrector for temperature controller W/m2<br/>2 Irradiance corrector for fan W/m2<br/>3 Value to be digitized.</p>\n<p><strong>3</strong> Irradiance sensor DX<br/>0 Irradiance not delayed (?) W/m2<br/>1 Irradiance correction for temperature controller W/m2<br/>2 Irradiance correction for fan W/m2<br/>3 Value to be digitized.</p>\n<p><strong>4</strong> Outdoor temperature<br/>0 Outdoor temperature °C<br/>1 Temp. Outdoor CAN line °C<br/>2 Intake air temperature climate °C </p>\n<p><strong>5</strong> Theoretical SX temperature<br/>0 Theoretical SX outlet air temp. °C<br/>1 Difference between theoretical and actual temp. °C<br/>2 Value of sx. regulation ½ % /Dig<br/>3 Stell-Max (?) ½ % /Dig<br/>4 Defrost SX    </p>\n<p><strong>6</strong> Noticed temperature SX<br/>0 Temp. Noticed SX °C<br/>1 Temp. Feet SX °C<br/>2 Temp. Frontal SX °C   </p>\n<p><strong>7</strong> Theoretical temperature DX<br/>0 Theoretical air temperature DX °C<br/>1 Difference between theoretical and actual temperature DX °C<br/>2 Control values controller ½ % /Dig<br/>3 Stell-Max (?) ½ % /Dig<br/>4 Defrost DX   </p>\n<p><strong>8</strong> Noticed temperature DX<br/>0 Noticed outlet air temp. DX °C<br/>1 Temp. Feet °C<br/>2 Temp. Frontal °C   </p>\n<p><strong>9</strong> Theoretical evaporator temperature<br/>0 Theoretical evaporator temperature °C<br/>1 Difference between theoretical and effective evaporator temp. °C<br/>2 Evaporator control values 5mA/Dig<br/>3 Evaporator control modes (see below)  </p>\n<p><strong>10</strong> Effective evaporator temperature<br/>0 Effective evaporator temperature °C<br/>1 Refrigerant pressure climate bar<br/>2 Average refrigerant temperature climate °C</p>\n<p><strong>11</strong> Compressore clim<br/>0 Theoretical electric power but<br/>1 Effective electric power but<br/>2 Max electric power but<br/>3 Kompressor PWM (0… 200) Dig<br/>4 Electric power compressore offset<br/>5 Electric power values<br/>6 Code compressore disinserito</p>\n<p><strong>12</strong> Fan climate<br/>0 Theoretical fan voltage V<br/>1 Manual control<br/>2 Fault code<br/>3 Riduction fan V<br/>4 Offset fan (from here to automatic mode) 0.1V</p>\n<p><strong>13</strong> Bocchette air temperature SX<br/>0 Theoretical value formattato %<br/>1 Theoretical value actual temp. Bocchette sx. Dig.<br/>2 Conferma el. temp. Bocchette sx. Dig.<br/>3 Limite plus grand temp. Bocchette sx. Dig.<br/>4 Limit min. temp. Bocchette sx. Dig.          </p>\n<p><strong>14</strong> Bocchette air temperature DX<br/>0 Theoretical value formattato %<br/>1 Theoretical value real temp. Bocchette dx Dig.<br/>2 Conferma el. temp. Bocchette dx Dig.<br/>3 Limite plus grand temp. Bocchette dx. Dig.<br/>4 Limit min. temp. Bocchette dx. Dig.        </p>\n<p><strong>15</strong> Temperature bocchetta pieds/centrale<br/>0 Theoretical value formattato %<br/>1 Actual theoretical value temp. Bocchetta centrale Dig.<br/>2 Conferma el. temp. bocchetta centrale Dig.<br/>3 Limite plus grand temp. bocchetta centrale Dig.<br/>4 Limite min. temp. bocchetta centrale Dig.      </p>\n<p><strong>16</strong> Pelle Defrost<br/>0 Theoretical value formattato %<br/>1 Actual theoretical value pelle Defrost Dig.<br/>2 Conferma el. pelle Defrost Dig.<br/>3 Limit plus pelle Defrost Dig.<br/>4 Limit min. pelle Defrost Dig.  </p>\n<p><strong>17</strong> Pelle ricircolo interne<br/>0 Valeur théorique formattato %<br/>1 Valeur théorique réelle pelle ricircolo Dig.<br/>2 Conferma el. pelle ricircolo Dig.<br/>3 Limite plus grand pelle ricircolo Dig.<br/>4 Limite min. pelle ricircolo Dig.  </p>\n<p><strong>18</strong> Cold air shovel<br/>0 Theoretical value formattato %<br/>1 Theoretical actual value Cold air shovel Dig.<br/>2 Conferma el. Pelle air froid Dig.<br/>3 Limite plus grand Pelle air froid Dig.<br/>4 Limite min. Cold air shovel Dig.  </p>\n<p><strong>19</strong> Motor data<br/>0 Speeds’ km/h<br/>1 Motor temperature °C<br/>2 Motor rpm U/min<br/>3 Compressor rpm climate U/min</p>\n<p><strong>20</strong> Data sent on CAN<br/>0 of Additional heating (on demand)1 = inserted<br/>1 Conferma el. PTC 1 = inserted<br/>2 Puissance el. effective PTC à 3% air demandé radiatore de<br/>clima%<br/>4 Rappo% de pic de l’air radiatore%<br/>5 Aucune prestation demandée au disp. de chauffage 1=nessuna prestation chauffage   </p>\n<p><strong>21</strong> Ripartitore d’air Climat<br/>0 Defrost% 1 Frontale%<br/>2 Piedi%<br/>3 Bocchetta areazione%<br/>4 Ricircolo air frais/propre (+ bocchetta… ?) %<br/>5 Évaluation sensore%</p>\n<p><strong>22</strong> Timer data<br/>0 Stop period min.<br/>1 Motor running time S<br/>2 Running time with key inserted s</p>\n<p><strong>23</strong> Special channel<br/>0 Internal lighting sensor Dig.<br/>1 Air quality sensor</p>\n<p><strong>24</strong> Software version<br/>0 Development status<br/>1 Software version<br/>2 Type SW<br/>3 Keep Frozen<br/>4 Version K Matrix<br/>5 EEP -Testflags<br/>6 Codifica Vag (?) 2</p>\n<p><strong>25</strong> Canali di prova<br/>0 Canale 0<br/>1 Canale1<br/>2 Canale2<br/>3 Canale3<br/>4 Canale4<br/>5 Canale5<br/>6 Canale6<br/>7 Canale7<br/>8 Canale8<br/>9 Canale9</p>\n<p><strong>26</strong> Parameters for readings on crystals<br/>0 I delay s<br/>1 Step/udm (?) digit<br/>2 Limit minimo digit<br/>3 Limit max. digit<br/>4 Step/udm on HellaKit (?) 1=ein </p>\n<p><strong>27</strong> Bocchetta areazione directe<br/>0 Theoretical value formattato%<br/>1 Actual theoretical value Bocchetta areazione directe Dig.<br/>2 Conferma el. Bocchetta areazione directe Dig.<br/>3 Limite max. Bocchetta areazione directe Dig.<br/>4 Limite min. Bocchetta areazione directe Dig.   </p>\n<p><strong>28</strong> Umidita<br/>0 Umidita’22#teorica%<br/>1 Umidita’relative to temperature UIF ? %<br/>2 Temp. WSS crystals °C<br/>3 Temperature of condensation °C<br/>4 Melting point temperature difference °C </p>\n<p><strong>29</strong> Raw values himidity<br/>0 Temp. Crystal, corrected °C<br/>1 Temp. Crystal, uncorrected °C<br/>2 Sensor umidità%<br/>3 Sensor temperature °C<br/>4 Condensation point temperature (test measurement) °C<br/>5 Fault code  </p>\n<p><strong>30</strong> Indicated values you himidity<br/>0 Sensor value termofil oDig.<br/>1 Temperatura rif. termofilo Dig.<br/>2 Periodic duration himidity 10-4 sec<br/>3 Temp. Reference himidity Dig.<br/>4 Himidity Rel. on sensore%<br/>5 Sensor temperature himidity °C<br/>6 Crystal temperature (uncorrected) °C   </p>\n<p><strong>What’s in it for me?</strong></p>\n<p>None, unless you like numbers, and the fact that you can see your speed in real time other than with a needle is very nice.</p>\n<p><strong>How do I get out of this menu?</strong></p>\n<p>By switching off the engine or pressing the “AUTO” and “ECON” buttons simultaneously.</p>","touran-1t-activate-daytime-running-lights-with-fog-lamps-drl":"<p><strong>Purpose</strong>: Allows fog lights to be used as daytime running lights.  </p>\n<p><strong>Procedure</strong>: <br/><strong>1</strong> – With the engine off and the ignition off, connect your official VAG-COM VCDS cable to the computer, then connect the other end to your vehicle’s diagnostic port.<br/><br/><strong>2</strong> – Turn on the ignition, then launch the VCDS program.<br/><br/><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><strong>6 –</strong> <em>Byte 0: </em><br/><em>Bit 4: Check “Daytime Running Lights (North America)”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/scandinavie_194-c7df4fa8.webp\"/></figure>\n<p><strong>7 – </strong> <em>Byte 17: </em><br/><em>Bit 4: Check “Daytime Running Light with dimmed Low Beam” (or “Daytime Running Light via Fog Lights,” depending on your version of VCDS)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/ab_975-e7b60077.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/veilleusejour3-c639151f.webp\"/></figure>\n<p><strong>8-</strong> Adjusting the fog light intensity (from 1% to 99%)</p>\n<p><em>Byte 20: </em><br/><em>Change the value in the Dec box</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/VagComByte20-adce5646.webp\"/></figure>"};
